' node conform.js --schema schema.json data.jsonl # exit 0 clean, 1 on first bad record\n' +
' cat data.jsonl | node conform.js --schema schema.json\n' +
' node conform.js --selftest\n\n' +
'CEILING: ' + CEILING + '\n');
