ck('wrong-type-fails', r.ok === false);
ck('wrong-type-field', r.verdict.field === 'id');

// out of range
r = conform(['{"id":1,"name":"x","score":2}'], schema);
ck('range-fails', r.ok === false && r.verdict.field === 'score');

