var ps = { code: { type: 'string', pattern: '^[A-Z]{3}$', required: true}};
ck('pattern-ok', conform(['{"code":"ABC"}'], ps).ok === true);
ck('pattern-fails', conform(['{"code":"abcd"}'], ps).ok === false);

