var goldenBins = [
{ lo: 1, hi: 2, count: 1},
{ lo: 2, hi: 3, count: 2},
{ lo: 3, hi: 4, count: 0},
{ lo: 4, hi: 5, count: 0},
{ lo: 5, hi: 6, count: 1}
