var FORMAT = "l21x";
var FORMAT_VERSION = 1;

/* encodeSnapshot(doc[, meta]) -> base64 string.
doc: any JSON-serializable value (the document body).
meta: optional {title, schema} recorded alongside. */
function encodeSnapshot(doc, meta) {
