errors.push("entry " + i + ": missing id");
else if (seen[e.id]) errors.push("entry " + i + ": duplicate id '" + e.id + "'");
else seen[e.id] = true;
if (typeof e.snapshot!== "string") { errors.push("entry " + i + ": snapshot is not a string");}
