fuchsia:1, green:1, lime:1, olive:1, yellow:1, navy:1, blue:1, teal:1,
aqua:1, cyan:1, magenta:1, orange:1, pink:1, brown:1, gold:1, coral:1,
salmon:1, khaki:1, violet:1, indigo:1, turquoise:1, tan:1, beige:1,
