check("missing field omitted (default)",
out('{"a":1}', { fields: ["a", "b"]}),
'{"a":1}');

check("record carrying none of the fields -> empty object",
out('{"x":9}', { fields: ["a", "b"]}),
'{}');

check("missing field in the MIDDLE keeps declared order of the rest",
out('{"a":1,"c":3}', { fields: ["a", "b", "c"]}),
'{"a":1,"c":3}');

