buffer = (buffer << 6) | v; bits += 6;
if (bits >= 8) { bits -= 8; out.push((buffer >> bits) & 0xff);}
}
return out;
}

// ---- quoted-printable (=XX bytes, soft line breaks) ------------------------
function decodeQuotedPrintable(str) {
