[-3, -1, 0, 2, 4],
[10, 20, 30, 40, 50, 60],
[42],
[1.5, 2.5, 0.5, 3.5],
[7, 7, 7, 7],
[100, -100, 0]
];
[1, 2, 3].forEach(function (k) {
vectors.forEach(function (v) {
